bool ScriptSession::alternateForm(const UnitState& u,const SpellInfo& s){return u.type==s.alternateType || (u.unitForm && u.unitForm->active && u.unitForm->spell.ability==s.ability);}
void ScriptSession::prepareUnitFormSpell(const UnitState& u,SpellInfo& s){if(!unitFormSpell(s.kind))return;if(alternateForm(u,s) && s.unorder){s.order=s.unorder;s.mana=0;if(s.kind!=SpellKind::StoneForm)s.cooldown=0;s.prerequisites.clear();}s.animation=alternateForm(u,s)?"Morph Alternate":"Morph";}
bool ScriptSession::unitFormReady(const UnitState& u,const SpellInfo& s,bool placement){
    if(u.building || u.illusion || u.formTransition || u.transport || u.grounded() || u.rooted())return false;bool reverse=alternateForm(u,s);if(reverse && (s.kind==SpellKind::Metamorphosis || (s.formFlags&8) || !s.unorder))return false;if(!reverse && u.type!=s.normalType)return false;if(!reverse && (s.formFlags&16)){auto& states=config_.players[u.owner].states;auto state=[&](unsigned key){auto i=states.find(key);return i==states.end()?0:i->second;};int extra=u.foodCounted?std::max(0,s.formFood-u.foodUsed):0;if(state(1)<s.formGold || state(2)<s.formLumber || (extra && state(5)>std::min(state(4),state(6))-extra))return false;}auto type=reverse?s.normalType:s.alternateType;return !placement || !u.airborne() || definitions().field(type,"UnitData","movetp")=="fly" || formLanding(u,type).has_value();
}
std::optional<WorldPoint> ScriptSession::formLanding(const UnitState& u,std::uint32_t type){
    float collision=std::max(0.f,definitions().number(type,"UnitBalance","collision",definitions().number(type,"UnitData","collision",16)));bool flying=definitions().property(type,"umvt",definitions().field(type,"UnitData","movetp"))=="fly";unsigned rings=gameplayNumber("MorphLandClosest",1)!=0?16:0;
    for(unsigned ring=0;ring<=rings;++ring)for(unsigned side=0;side<(ring?32u:1u);++side){float angle=float(side)*6.28318530718f/32;auto p=requireWorld().clamp({real(number(u.x)+std::cos(angle)*ring*32),real(number(u.y)+std::sin(angle)*ring*32)});float x=number(p.x),y=number(p.y);if(u.pathing){auto route=requireWorld().route(p,p,collision,flying);if(route.empty() || std::hypot(number(route.back().x)-x,number(route.back().y)-y)>1)continue;}bool free=true;for(auto& [id,other]:units_)if(id!=u.handle && !other->hidden() && other->pathing && number(other->life)>0 && other->airborne()==flying && std::hypot(number(other->x)-x,number(other->y)-y)<collision+other->collision){free=false;break;}if(free)return p;}return {};
}
bool ScriptSession::changeUnitForm(std::uint32_t id,std::uint32_t type,float healthBonus,bool heroForm){
    if(!alive(id,NativeKind::Unit))return false;auto u=units_.at(id);UnitState previous,next;previous.owner=next.owner=u->owner;initializeUnitType(previous,u->type);initializeUnitType(next,type);if(next.hero!=u->hero || next.building!=u->building)throw std::runtime_error("Unit form cannot change hero or structure classification");initializeCommerce(next);refreshResearch(next);initializeHarvest(next);
    for(auto [ability,level]:u->abilities){if(!previous.abilities.contains(ability) || (u->permanentAbilities.contains(ability) && u->permanentAbilities.at(ability)))next.abilities[ability]=level;else if(next.abilities.contains(ability))next.abilities[ability]=std::max(1,level+next.technology.abilityLevels[ability]-u->technology.abilityLevels[ability]);}for(auto [ability,level]:previous.abilities)if(!u->abilities.contains(ability))next.abilities.erase(ability);
    float before=number(u->maxLife),life=number(u->life),hp=number(next.maxLife)-number(previous.maxLife)-u->technology.health+healthBonus,mp=number(next.maxMana)-number(previous.maxMana)-u->technology.mana;int used=u->foodUsed,made=u->foodMade,reserved=u->formTransition?u->formTransition->food:0;if(u->formTransition)u->formTransition->food=0;u->type=type;u->name=std::move(next.name);u->model=std::move(next.model);u->icon=std::move(next.icon);u->animationProperties=std::move(next.animationProperties);u->maxLife=real(std::max(1.f,before+hp));u->life=real(life<=0?0:std::clamp(heroForm?life+hp:life/std::max(1.f,before)*number(u->maxLife),1.f,number(u->maxLife)));u->maxMana=real(std::max(0.f,number(u->maxMana)+mp));u->mana=real(std::clamp(number(u->mana),0.f,number(u->maxMana)));
    u->moveSpeed=real(std::max(0.f,number(u->moveSpeed)+number(next.moveSpeed)-number(previous.moveSpeed)-u->technology.movement));u->defaultMoveSpeed=next.defaultMoveSpeed;u->acquireRange=real(std::max(0.f,number(u->acquireRange)+number(next.acquireRange)-number(previous.acquireRange)));u->scale=next.scale;u->selectionSize=next.selectionSize;u->collision=next.collision;u->movementType=std::move(next.movementType);u->race=next.race;if(!u->hero)u->level=next.level;u->abilities=std::move(next.abilities);std::erase_if(u->autocast,[&](auto& entry){return !u->abilities.contains(entry.first);});for(auto [ability,on]:next.autocast)u->autocast.try_emplace(ability,on);u->upgrades=std::move(next.upgrades);u->technology=std::move(next.technology);u->trainables=std::move(next.trainables);u->researches=std::move(next.researches);u->upgradeables=std::move(next.upgradeables);u->buildables=std::move(next.buildables);u->burrowed=next.burrowed;u->formHealthRegen=next.formHealthRegen;u->healthRegen=next.healthRegen;u->manaRegen=next.manaRegen;u->regenType=std::move(next.regenType);u->foodUsed=next.foodUsed;u->foodMade=next.foodMade;u->route.clear();u->waypoint=0;unitFootprint(*u);++fogRevision_;int foodDelta=(u->foodCounted?u->foodUsed-used:0)-reserved,capacityDelta=u->foodCounted?u->foodMade-made:0;if(foodDelta || capacityDelta)adjustFood(u->owner,foodDelta,capacityDelta);return alive(id,NativeKind::Unit) && !u->removing && u->type==type;
}
bool ScriptSession::commitUnitForm(std::uint32_t id){
    if(!alive(id,NativeKind::Unit))return false;auto u=units_.at(id);if(!u->formTransition || !u->unitForm)return false;auto transition=*u->formTransition;auto& s=transition.spell;bool landing=u->airborne() && definitions().property(transition.type,"umvt",definitions().field(transition.type,"UnitData","movetp"))!="fly";if(landing){auto p=formLanding(*u,transition.type);if(!p)return false;u->x=p->x;u->y=p->y;}float bonus=transition.reverse?-u->unitForm->healthApplied:s.formHealth;u->formTransition->committed=true;u->unitForm->active=!transition.reverse;u->unitForm->healthApplied=transition.reverse?0:s.formHealth;if(!changeUnitForm(id,transition.type,bonus,s.kind==SpellKind::Metamorphosis) || !u->formTransition || u->formTransition->ticket!=transition.ticket)return false;if(s.kind==SpellKind::AvengerForm && !transition.reverse)u->mana=real(std::clamp(definitions().number(transition.type,"UnitBalance","mana0"),0.f,number(u->maxMana)));u->targetFlyHeight=definitions().number(transition.type,"UnitData","moveHeight");u->flyRate=s.heightTime>0?std::abs(u->targetFlyHeight-u->flyHeight)/s.heightTime:0;if(!u->flyRate)u->flyHeight=u->targetFlyHeight;return true;
}
void ScriptSession::startUnitForm(std::uint32_t id,const CastOrder& cast){
    if(!alive(id,NativeKind::Unit))return;auto u=units_.at(id);auto& s=cast.spell;if(!unitFormReady(*u,s)){cancelCast(*u);return;}bool reverse=alternateForm(*u,s);if(!u->unitForm)u->unitForm=UnitFormState{s,reverse,0,-1};UnitFormTransition transition;transition.spell=s;transition.type=reverse?s.normalType:s.alternateType;transition.reverse=reverse;transition.ticket=cast.ticket;transition.previousHeight=u->targetFlyHeight;transition.previousRate=u->flyRate;transition.payer=u->owner;bool landing=u->airborne() && definitions().property(transition.type,"umvt",definitions().field(transition.type,"UnitData","movetp"))!="fly";transition.remaining=s.duration+(landing?s.landDelay:0);u->formTransition=transition;u->cast->phase=CastOrder::Phase::Channel;u->animation=s.animation;u->animationTime=0;u->animationIndex.reset();u->animationQueue.clear();u->route.clear();u->waypoint=0;unitFormActors_.insert(id);
    auto current=[&]{return alive(id,NativeKind::Unit) && !u->removing && u->formTransition && u->formTransition->ticket==cast.ticket && u->cast && u->cast->ticket==cast.ticket;};if(!reverse && (s.formFlags&16)){auto owner=u->owner;auto& states=config_.players[owner].states;int gold=states[1],lumber=states[2],food=u->foodCounted?std::max(0,s.formFood-u->foodUsed):0;u->formTransition->gold=s.formGold;u->formTransition->lumber=s.formLumber;u->formTransition->food=food;states[1]-=s.formGold;states[2]-=s.formLumber;int nextGold=states[1],nextLumber=states[2];if(food)adjustFood(owner,food,0);if(!current())return;playerChange(owner,1,gold,nextGold,false);if(!current())return;playerChange(owner,2,lumber,nextLumber,false);if(!current())return;}
    if(landing){u->targetFlyHeight=definitions().number(transition.type,"UnitData","moveHeight");u->flyRate=s.heightTime>0?std::abs(u->targetFlyHeight-u->flyHeight)/s.heightTime:0;if(!u->flyRate)u->flyHeight=u->targetFlyHeight;}
    bool immediate=landing?(s.formFlags&2)!=0:(s.formFlags&4)!=0;if(immediate && !commitUnitForm(id)){if(current())cancelCast(*u);return;}if(current())spellVisual(s,"CasterArt",id,{u->x,u->y});
}
void ScriptSession::cancelUnitForm(UnitState& u,std::uint64_t ticket){
    if(!u.formTransition || u.formTransition->ticket!=ticket)return;auto transition=*u.formTransition;u.formTransition.reset();if(!transition.committed){u.targetFlyHeight=transition.previousHeight;u.flyRate=transition.previousRate;if(!u.flyRate)u.flyHeight=u.targetFlyHeight;}if(u.unitForm && !u.unitForm->active)u.unitForm.reset();if(!u.unitForm)unitFormActors_.erase(u.handle);if(transition.committed)return;auto& states=config_.players[transition.payer].states;int gold=states[1],lumber=states[2];int nextGold=states[1]=int(std::min(std::int64_t(INT_MAX),std::int64_t(gold)+transition.gold)),nextLumber=states[2]=int(std::min(std::int64_t(INT_MAX),std::int64_t(lumber)+transition.lumber));if(transition.food)adjustFood(transition.payer,-transition.food,0);if(transition.gold)playerChange(transition.payer,1,gold,nextGold,false);if(transition.lumber)playerChange(transition.payer,2,lumber,nextLumber,false);
}
void ScriptSession::returnUnitForm(std::uint32_t id){
    if(!alive(id,NativeKind::Unit))return;auto u=units_.at(id);if(!u->unitForm || !u->unitForm->active || u->formTransition)return;auto s=u->unitForm->spell;if(!cancelCombat(*u) || !alive(id,NativeKind::Unit) || !u->unitForm || u->formTransition)return;UnitFormTransition transition;transition.spell=s;transition.type=s.normalType;transition.reverse=true;transition.remaining=s.duration;transition.previousHeight=u->targetFlyHeight;transition.previousRate=u->flyRate;u->formTransition=transition;u->animation="Morph Alternate";u->animationTime=0;u->animationIndex.reset();u->animationQueue.clear();u->route.clear();u->waypoint=0;unitFormActors_.insert(id);
}
void ScriptSession::unitFormsTick(double delta){
    std::vector<std::uint32_t> actors(unitFormActors_.begin(),unitFormActors_.end());for(auto id:actors){if(!alive(id,NativeKind::Unit)){unitFormActors_.erase(id);continue;}auto u=units_.at(id);if(u->removing || number(u->life)<=0){unitFormActors_.erase(id);continue;}if(u->paused)continue;
        if(u->formTransition){auto transition=*u->formTransition;if(transition.ticket && (!u->cast || u->cast->ticket!=transition.ticket)){cancelUnitForm(*u,transition.ticket);continue;}bool controlled=false;for(auto& [buff,b]:u->buffs)if(b.kind==BuffKind::Stun || b.kind==BuffKind::Sleep || b.kind==BuffKind::Cyclone || b.kind==BuffKind::Morph)controlled=true;if(controlled && !(transition.spell.formFlags&1)){if(transition.ticket)cancelCast(*u);else cancelUnitForm(*u,0);continue;}u->formTransition->remaining-=delta;if(u->formTransition->remaining>0)continue;auto& s=transition.spell;
            if(!transition.committed && !commitUnitForm(id)){if(alive(id,NativeKind::Unit) && u->formTransition && u->formTransition->ticket==transition.ticket)u->formTransition->remaining=.25;continue;}if(!u->formTransition || !u->unitForm || u->formTransition->ticket!=transition.ticket)continue;
            u->formTransition.reset();if(transition.reverse){if(s.buff){auto b=u->buffs.find(s.buff);if(b!=u->buffs.end() && b->second.kind==BuffKind::UnitForm){releaseBuff(b->second);u->buffs.erase(b);}}u->unitForm.reset();unitFormActors_.erase(id);}else {u->unitForm->remaining=s.heroDuration>0 && !(s.formFlags&8)?s.heroDuration:-1;if(s.buff){UnitBuff b;b.id=s.buff;b.source=b.target=id;b.kind=BuffKind::UnitForm;b.remaining=std::max(0.,u->unitForm->remaining);b.persistent=true;b.positive=true;b.physical=true;b.dispellable=false;u->buffs[s.buff]=std::move(b);}if(u->unitForm->remaining<0)unitFormActors_.erase(id);}if(transition.ticket)finishCast(id,transition.ticket);else {u->animation.clear();u->animationTime=0;}continue;
        }
        if(!u->unitForm || !u->unitForm->active || u->unitForm->remaining<0){unitFormActors_.erase(id);continue;}u->unitForm->remaining=std::max(0.,u->unitForm->remaining-delta);if(auto b=u->buffs.find(u->unitForm->spell.buff);b!=u->buffs.end())b->second.remaining=u->unitForm->remaining;if(u->unitForm->remaining<=0)returnUnitForm(id);
    }
}
void ScriptSession::unitFormDeath(UnitState& u){
    u.formTransition.reset();unitFormActors_.erase(u.handle);if(u.unitForm && u.unitForm->active && u.unitForm->spell.kind==SpellKind::Metamorphosis){auto state=*u.unitForm;u.unitForm.reset();changeUnitForm(u.handle,state.spell.normalType,-state.healthApplied,true);}else if(u.unitForm && !u.unitForm->active)u.unitForm.reset();
}
